// === Tab: Splines ===
class Spline {
	constructor(x, y, d = 10) {
		this.x = x;
		this.y = y;
		this.d = d;

		this.pts = []
		for (let i = 0; i < 3; i++) {
			const dx = random(d * 0.5, d);
			const dy = random(d * 0.5, d);
			const sx = Math.sign(sin(i * TWO_PI / 4))
			const sy = Math.sign(cos(i * TWO_PI / 4))
			this.pts.push({
				x: sx * dx,
				y: sy * dy
			})
		}

		this.p = random() < 0.5 ? palettes[5] : random(palettes);
	}

	show(n = 1, d = 0) {
		push()
		for (let i = 0; i < n; i++) {
			// splineTightness(random())
			randomStroke()
			const clr = color(this.p[i % this.p.length])
			clr.setAlpha(228)
			stroke(clr)
			noStroke;
			randomStroke(this.p)
			beginShape()

			if (false) {
				for (let p of this.pts) {
					const dx = random(-d, d);
					const dy = random(-d, d);
					vertex(this.x + p.x + dx, this.y + p.y + dy)
				}
			}

			if (true) {
				for (let i = 0; i < this.pts.length + 2; i++) {
					const p = this.pts[i % this.pts.length];
					const dx = random(-d, d);
					const dy = random(-d, d);
					splineVertex(this.x + p.x + dx, this.y + p.y + dy)
				}
			}

			endShape(CLOSE)
		}
		pop()
	}
}

