let shapes;
let minWH, d;
let pal;

const palettes = [
	["#e96d5e", "#ff9760", "#ffe69d", "#6a7e6a", "#393f5f"],
	["#af43be", "#fd8090", "#c4ffff", "#08deea", "#1261d1"],
	["#a0ffe3", "#65dc98", "#8d8980", "#575267", "#222035"],
	["#ff2a6d", "#d1f7ff", "#f5d9e8", "#005678", "#01012b"],
	["#8f704b", "#daae6d", "#89e3f6", "#4d9e9b", "#44786a"],
	["#b0acb0", "#e2dddf", "#85ebd9", "#3d898d", "#2f404d"],
	["#ff184c", "#ff577d", "#ffccdc", "#0a9cf5", "#003062"],
]

function setup() {
	createA4Canvas();
	describe("curved dashed lines with various thickness and colors")
	// global vars
	minWH = max(width, height);

	noFill();
	stroke(212); // 232
	strokeWeight(2);
	strokeCap(SQUARE);
	strokeJoin(ROUND);

	shapes = [];
	for (let i = 0; i < 3; i++) {
		d = getRandDiameter()
		shapes.push(new Spline(0, 0, d))
		d = getRandDiameter()
		shapes.push(new Spline(width, 0, d))
		d = getRandDiameter()
		shapes.push(new Spline(width, height, d))
		d = getRandDiameter()
		shapes.push(new Spline(0, height, d))

		// remove random shape
		shapes.splice(~~random(shapes.length), 1)
	}
}

function windowResized() {
	createA4Canvas();
}

function createA4Canvas() {
	const portraitRatio = 210 / 297;
	const landscapeRatio = 1 / portraitRatio;

	const useLandscape = windowWidth > windowHeight;
	const a4 = useLandscape ? landscapeRatio : portraitRatio;

	let w = windowWidth;
	let h = windowHeight;

	let targetW = w;
	let targetH = w / a4;
	if (targetH > h) {
		targetH = h;
		targetW = h * a4;
	}

	resizeCanvas(targetW, targetH);
}

function getRandDiameter() {
	return random(minWH * 0.45, minWH * 0.75);
}

function draw() {
  // === Variant 2: Organic Lissajous Morph ===
  scalePulse = 1.0 + 0.25 * sin(frameCount * 0.03);
  rotAngle = frameCount * 0.015;
  push();
  translate(width/2, height/2);
  rotate(rotAngle);
  scale(scalePulse);
  translate(-width/2, -height/2);

	background("beige");

	if (random() < 0.5) {
		stroke("#04041040")
		strokeWeight(1.1)
		for (let d = random(25, 40), y = d / 2; y < height - d / 3; y += d)
			line(3, y, width - 3, y)

	} else {
		stroke("#04041080")
		strokeWeight(1.6)
		const d = random(10, 50);
		for (let y = d / 2; y < height - d; y += d)
			for (let x = d / 3; x < width - d / 2; x += d)
				point(x, y)
	}

	// splines
	noFill()
	stroke(255);
	for (let s of shapes) {
		s.show(random(2, 6), ~~random(0.02, 0.05) * minWH)
	}

	// circles
	const numC = random(1, 3); // num circles: 1 or 2
	for (let j = 0; j < numC; j++) {
		const numV = random(2, 6); // num variations of circle: 2..5
		const cx = random(-width * 0.2, width * 1.2)
		const cy = random(-height * 0.2, height * 1.2)
		const d = getRandDiameter() * 1.5
		const pal = random(palettes)
		for (let i = 0; i < numV; i++) {
			// fill(random(160, 255))
			randomStroke(pal)
			const dx = random(d * 0.01, d * 0.025);
			const dy = random(d * 0.01, d * 0.025);
			circle(cx + random(-dx, dx), cy + random(-dy, dy), d);
		}
	}

	// frame
	noFill()
	stroke("rgba(245,245,220,0.8)")
	drawingContext.setLineDash([])
	const pad = minWH * 0.05;
	strokeWeight(pad)
	rect(0, 0, width, height)
	rect(0, 0, width, height, pad * 0.75)
	// rect(0, 0, width, height, pad * 0.5)

	noLoop();

  pop();
}

function mouseClicked() {
	// if (mouseButton === LEFT) loop()
	setup()
	loop()
	// console.log(frameCount)
}

function randomStroke(pal = null) {
	strokeWeight(~~random(10, 200));
	const n = ~~random(1, 4)
	const list = []
	for (let i = 0; i < n; i++) {
		list.push(~~random(2, random(2, 200)))
	}
	drawingContext.setLineDash(list);

	stroke(random(255), random(100), random(255), random(100, 200)); // random(150, 255)
	if (pal) {
		const clr = color(random(pal))
		clr.setAlpha(random(100, 200))
		stroke(clr)
	}
	// stroke(random(255), random(150, 255))
	return list;
}

